import assert from 'node:assert/strict';
import {readFileSync,writeFileSync} from 'node:fs';
import {dualraySamples} from './current/tests/helpers/dualray-samples.js';
import {createReference} from './current/tests/helpers/css-minde-reference.js';
const samples=dualraySamples('display-p3'),ref=createReference('display-p3');
const current=(await import('./current/src/dualray.js')).dualray;
const expected=samples.map(input=>current(input,[]));const report=[];
for(const variant of JSON.parse(readFileSync(new URL('./variant-names.json',import.meta.url)))) {
 const map=(await import(`./${variant}/src/dualray.js`)).dualray;
 let changed=0,linear=0,encoded=0;
 for(let i=0;i<samples.length;i++) {
  const out=[NaN,NaN,NaN];assert.equal(map(samples[i],out),out);assert.ok(out.every(Number.isFinite));
  const a=expected[i];if(out.some((v,j)=>v!==a[j]))changed++;
  for(let j=0;j<3;j++){linear=Math.max(linear,Math.abs(ref.decode(out[j])-ref.decode(a[j])));encoded=Math.max(encoded,Math.abs(out[j]-a[j]));}
 }
 if(!['baseline','old-math'].includes(variant))assert.equal(changed,0,variant);
 else assert.ok(linear<1e-13&&encoded<1e-13,variant);
 report.push({variant,samples:samples.length,changed,linear,encoded});
}
console.log(JSON.stringify({runtime:process.versions,report},null,2));

